1467	/**
1468	 * @brief 在 BAS 仍留在 GATTC 表里时缓存 0x2A19 handle。
1469	 *
1470	 * 板卡 SAL keep_db 后第二次发现不会冲掉该 handle。
1471	 */
1472	static void slot_cache_bat_handle(struct sensor_slot *slot)
1473	{
1474	  bt_uuid_t        uuid;
1475	  gatt_attr_desc_t desc;
1476	
1477	  uuid = BT_UUID_DECLARE_16(UUID_BAT_LEVEL);
1478	  memset(&desc, 0, sizeof(desc));
1479	  if (bt_gattc_get_attribute_by_uuid(slot->gatt, 0x0001, 0xffff,
1480	                                     &uuid, &desc) != BT_STATUS_SUCCESS)
1481	    {
1482	      pthread_mutex_lock(&g_lock);
1483	      slot->bat_h      = 0;
1484	      slot->bat_notify = false;
1485	      slot->feat      &= (uint16_t)~SENSOR_FEAT_BAT;
1486	      pthread_mutex_unlock(&g_lock);
1487	      return;
1488	    }
1489	
1490	  /* 字段写在锁内；SAL 查询本身在锁外（见上）。 */
1491	  pthread_mutex_lock(&g_lock);
1492	  slot->bat_h  = desc.handle;
1493	  slot->feat  |= SENSOR_FEAT_BAT;
1494	  pthread_mutex_unlock(&g_lock);
1495	  LOGD("%s bat handle 0x%04x%s", kind_name(slot->kind),
1496	       (unsigned)slot->bat_h,
1497	       (desc.properties & GATT_PROP_NOTIFY) ? " (notify)" : " (read)");
1498	}
