1500	/**
1501	 * @brief UUID 发现完成：先 BAS 缓存电量 handle，再槽位服务，再订测量和电量。
1502	 *
1503	 * 板卡 SAL 第二次发现追加表，BAS 的 0x2A19 仍可查找/订阅。
1504	 */
1505	static void gattc_on_discovered(gattc_handle_t h, gatt_status_t status,
1506	                                bt_uuid_t *uuid, uint16_t start_handle,
1507	                                uint16_t end_handle)
1508	{
1509	  struct sensor_slot *slot = slot_by_gatt(h);
1510	  uint16_t u16;
1511	  char feats[24];
1512	
1513	  if (slot == NULL)
1514	    {
1515	      return;
1516	    }
1517	
1518	  if (status != GATT_STATUS_SUCCESS)
1519	    {
1520	      if (slot->disc_step == 0)
1521	        {
1522	          LOGI("%s battery skip status %d", kind_name(slot->kind),
1523	               (int)status);
1524	          slot->disc_step = 1;
1525	          slot->state     = SENSOR_DISCOVERING;
1526	          slot->op_sent   = false;
1527	          slot->state_ms  = sensor_now_ms();
1528	          return;
1529	        }
1530	
1531	      LOGE("%s discover status %d", kind_name(slot->kind), (int)status);
1532	      slot->drop_link = true;
1533	      return;
1534	    }
1535	
1536	  if (uuid != NULL && uuid->type != 0)
1537	    {
1538	      u16 = uuid16_of(uuid);
1539	      if (u16 == UUID_HRS)
1540	        {
1541	          slot->feat |= SENSOR_FEAT_HR;
1542	        }
1543	      else if (u16 == UUID_CSCS)
1544	        {
1545	          slot->feat |= SENSOR_FEAT_CSC;
1546	        }
1547	      else if (u16 == UUID_CPS)
1548	        {
1549	          slot->feat |= SENSOR_FEAT_CPS;
1550	        }
1551	
1552	      LOGD("%s svc 0x%04x handles %04x-%04x", kind_name(slot->kind),
1553	           (unsigned)u16, (unsigned)start_handle, (unsigned)end_handle);
1554	      return;
1555	    }
1556	
1557	  mask_str(slot->feat, feats, sizeof(feats));
1558	  LOGD("%s discover done feat=%s", kind_name(slot->kind), feats);
1559	
1560	  if (slot->disc_step == 0)
1561	    {
1562	      /* gattc_locked_discovered 已持锁。slot_cache_bat_handle 内部要查 SAL
1563	       * （bt_gattc_get_attribute_by_uuid），约定是绝不在持锁时碰 SAL —— 否则
1564	       * 一旦该调用需要 service-loop 线程配合，而 service-loop 正等这把锁，
1565	       * 就是死锁。这里显式让出锁，查完再拿回来。 */
1566	      pthread_mutex_unlock(&g_lock);
1567	      slot_cache_bat_handle(slot);
1568	      pthread_mutex_lock(&g_lock);
1569	      slot->disc_step = 1;
1570	      slot->state     = SENSOR_DISCOVERING;
1571	      slot->op_sent   = false;
1572	      slot->state_ms  = sensor_now_ms();
1573	      LOGD("%s discover 0x%04x", kind_name(slot->kind),
1574	           (unsigned)kind_svc_uuid(slot->kind));
1575	      return;
1576	    }
1577	
1578	  if ((slot->feat & kind_feat_bit(slot->kind)) == 0)
1579	    {
1580	      LOGE("%s discover missing 0x%04x", kind_name(slot->kind),
1581	           (unsigned)kind_svc_uuid(slot->kind));
1582	      slot->drop_link = true;
1583	      return;
1584	    }
1585	
1586	  slot->state    = SENSOR_SUBSCRIBING;
1587	  slot->state_ms = sensor_now_ms();
1588	  slot->op_sent  = false;
1589	  slot->sub_step = 0;
1590	}
