1592	/**
1593	 * @brief CCC 写完；pump 推进 sub_step（测量，然后电量若有 Notify）。
1594	 */
1595	static void gattc_on_subscribed(gattc_handle_t h, gatt_status_t status,
1596	                                uint16_t attr_handle, bool enable)
1597	{
1598	  struct sensor_slot *slot = slot_by_gatt(h);
1599	
1600	  if (slot == NULL)
1601	    {
1602	      return;
1603	    }
1604	
1605	  if (status == GATT_STATUS_SUCCESS && enable)
1606	    {
1607	      LOGD("%s notify on handle 0x%04x", kind_name(slot->kind),
1608	           (unsigned)attr_handle);
1609	      slot->sub_fail = 0;
1610	      if (attr_handle == slot->hr_h || attr_handle == slot->csc_h ||
1611	          attr_handle == slot->cps_h)
1612	        {
1613	          slot->meas_sub_ok = true;
1614	          slot->sub_step    = 1;
1615	        }
1616	      else if (attr_handle == slot->bat_h)
1617	        {
1618	          slot->sub_step = 2;
1619	        }
1620	    }
1621	  else
1622	    {
1623	      LOGE("%s subscribe status %d handle=0x%04x enable=%d",
1624	           kind_name(slot->kind), (int)status, (unsigned)attr_handle,
1625	           (int)enable);
1626	      slot->sub_fail++;
1627	      if (slot->sub_fail >= SENSOR_SUB_RETRY_MAX)
1628	        {
1629	          slot->drop_link = true;
1630	        }
1631	    }
1632	
1633	  slot->op_sent = false;
1634	}
