1637	 * @brief 拷贝 notify 载荷，由 pump 解析。刷新 notify_ms（8 s 过期）。
1638	 */
1639	static void gattc_on_notified(gattc_handle_t h, uint16_t attr_handle,
1640	                              uint8_t *value, uint16_t length)
1641	{
1642	  struct sensor_slot *slot = slot_by_gatt(h);
1643	  uint16_t uuid = 0;
1644	
1645	  if (slot == NULL || value == NULL)
1646	    {
1647	      return;
1648	    }
1649	
1650	  if (attr_handle == slot->hr_h)
1651	    {
1652	      uuid = UUID_HR_MEAS;
1653	      slot->notify_ms = sensor_now_ms();
1654	      slot->meas_idle = false;
1655	      slot->adv_live  = 0;
1656	    }
1657	  else if (attr_handle == slot->csc_h)
1658	    {
1659	      uuid = UUID_CSC_MEAS;
1660	      slot->notify_ms = sensor_now_ms();
1661	      slot->meas_idle = false;
1662	      slot->adv_live  = 0;
1663	    }
1664	  else if (attr_handle == slot->cps_h)
1665	    {
1666	      uuid = UUID_CP_MEAS;
1667	      slot->notify_ms = sensor_now_ms();
1668	      slot->meas_idle = false;
1669	      slot->adv_live  = 0;
1670	    }
1671	  else if (attr_handle == slot->bat_h)
1672	    {
1673	      parse_bat(slot, value, length);
1674	    }
1675	
1676	  if (uuid != 0)
1677	    {
1678	      apply_meas(slot, uuid, value, length, sensor_now_ms());
