1682	/**
1683	 * @brief 体感位置（或其它）读完成。停车探活失败则拆链重连。
1684	 */
1685	static void gattc_on_read(gattc_handle_t h, gatt_status_t status,
1686	                          uint16_t attr_handle, uint8_t *value, uint16_t length)
1687	{
1688	  struct sensor_slot *slot = slot_by_gatt(h);
1689	  bool was_probe;
1690	
1691	  if (slot == NULL)
1692	    {
1693	      return;
1694	    }
1695	
1696	  was_probe = slot->probe_sent &&
1697	              (attr_handle == slot->bat_h || attr_handle == slot->csc_h ||
1698	               attr_handle == slot->cps_h || attr_handle == slot->hr_h);
1699	  if (was_probe)
1700	    {
1701	      slot->probe_sent = false;
1702	    }
1703	
1704	  if (status != GATT_STATUS_SUCCESS || value == NULL)
1705	    {
1706	      if (was_probe && slot_keep_link(slot) &&
1707	          (slot->meas_idle || slot->kind == SENSOR_KIND_HR))
1708	        {
1709	          LOGI("%s idle ATT status %d, reconnect",
1710	               kind_name(slot->kind), (int)status);
1711	          slot->drop_link = true;
1712	        }
1713	
1714	      return;
1715	    }
1716	
1717	  if (was_probe && slot->kind == SENSOR_KIND_HR)
1718	    {
1719	      slot->notify_ms = sensor_now_ms();
1720	    }
1721	
1722	  if (attr_handle == slot->bat_h)
1723	    {
1724	      parse_bat(slot, value, length);
1725	    }
1726	  else if (attr_handle == slot->loc_h)
1727	    {
1728	      parse_loc(slot, value, length);
1729	    }
1730	}
