381	/**
382	 * @brief @p a 全 0 则为 true（槽位未绑定）。
383	 */
384	static bool addr_empty(const bt_address_t *a)
385	{
386	  static const uint8_t z[BT_ADDR_LENGTH];
387	
388	  return memcmp(a->addr, z, BT_ADDR_LENGTH) == 0;
389	}
