391	static void slot_bind_addr(struct sensor_slot *slot, const bt_address_t *addr,
392	                           uint8_t addr_type, int8_t rssi, const char *name,
393	                           bool seen)
394	{
395	  uint32_t now = sensor_now_ms();
396	
397	  /* 多字段整体更新必须原子：ble_sensor_owns_addr() 在 BT 线程做 6 字节
398	   * memcmp，读到写了一半的地址时既不等于旧值也不等于新值 —— 手机可能被
399	   * 判成传感器（反之亦然），文件传输状态就此套到传感器链路上。
400	   * 调用方都是 companion 线程（不在持锁回调内），所以这里自己加锁安全。 */
401	  pthread_mutex_lock(&g_lock);
402	  slot->addr       = *addr;
403	  slot->addr_type  = addr_type;
404	  slot->rssi       = rssi;
405	  slot->seen_ms    = now;
406	  slot->state_ms   = 0;
407	  slot->retry_ms   = 0;
408	  slot->skip_dwell = seen;
409	  slot->want_link  = true;
410	  slot->adv_seen   = seen;
411	  slot->state      = SENSOR_IDLE;
412	  slot->op_sent    = false;
413	  memset(slot->name, 0, sizeof(slot->name));
414	  if (name != NULL && name[0] != '\0')
415	    {
416	      size_t n = strlen(name);
417	
418	      if (n >= SENSOR_NAME_MAX)
419	        {
420	          n = SENSOR_NAME_MAX - 1u;
421	        }
422	
423	      memcpy(slot->name, name, n);
424	    }
425	
426	  pthread_mutex_unlock(&g_lock);
427	}
