509	 * @brief GATTC 或 HCI 备份确认断链后回收槽位（可重入：已 IDLE 则忽略）。
510	 */
511	static void slot_handle_disconnected(struct sensor_slot *slot)
512	{
513	  char a[BT_ADDR_STR_LENGTH];
514	  bool keep;
515	  bool early;
516	  bool rearm;
517	  uint8_t reason;
518	
519	  if (slot == NULL || slot->state == SENSOR_IDLE)
520	    {
521	      return;
522	    }
523	
524	  bt_addr_ba2str(&slot->addr, a);
525	  keep   = slot_keep_link(slot);
526	  early  = (slot->state == SENSOR_CONNECTING ||
527	            slot->state == SENSOR_DISCOVERING);
528	  rearm  = slot->rearm_adv;
529	  reason = slot->hci_reason;
530	
531	  if (keep)
532	    {
533	      if (early)
534	        {
535	          LOGI("%s connect failed %s, scanning", kind_name(slot->kind), a);
536	        }
537	      else
538	        {
539	          LOGI("%s disconnected %s, scanning to reconnect",
540	               kind_name(slot->kind), a);
541	        }
542	    }
543	  else
544	    {
545	      LOGI("%s disconnected %s", kind_name(slot->kind), a);
546	    }
547	
548	  slot_idle_keep_addr(slot, sensor_now_ms());
549	
550	  if (!keep)
551	    {
552	      uint8_t k = slot->kind;
553	
554	      slot->want_link = false;
555	      /* addr/name 清零与 ble_sensor_owns_addr 的 memcmp 互斥（同 slot_bind_addr）。
556	       * 注意只包住这两行：后面的 slot_bind_addr 自己会加锁，不能嵌套。 */
557	      pthread_mutex_lock(&g_lock);
558	      memset(&slot->addr, 0, sizeof(slot->addr));
559	      memset(slot->name, 0, sizeof(slot->name));
560	      pthread_mutex_unlock(&g_lock);
561	      if (g_pending_bind[k].valid)
562	        {
563	          slot_bind_addr(slot, &g_pending_bind[k].addr,
564	                         g_pending_bind[k].addr_type, 0,
565	                         g_pending_bind[k].name, false);
566	          g_pending_bind[k].valid = false;
567	        }
568	
569	      sensor_ui_publish();
570	      return;
571	    }
572	
573	  if (rearm)
574	    {
575	      slot->adv_seen   = true;
576	      slot->skip_dwell = true;
577	      LOGI("%s already saw advertiser, connect now", kind_name(slot->kind));
578	    }
579	
580	  {
581	    uint32_t cool = SENSOR_RECONNECT_MS;
582	
583	    if (reason == HCI_ERR_CONN_FAIL_TO_ESTAB)
584	      {
585	        cool = SENSOR_RECONNECT_3E_MS;
586	      }
587	    else if (!rearm && (early || sensor_ready_count() >= 1))
588	      {
589	        cool = SENSOR_RECONNECT_BUSY_MS;
590	      }
591	
592	    slot->retry_ms = sensor_now_ms() + cool;
593	  }
594	  sensor_ui_publish();
595	}
