638	    {
639	      off += (size_t)snprintf(buf + off, n - off, "%sHR", off ? "+" : "");
640	    }
641	
642	  if ((mask & SENSOR_FEAT_CSC) != 0 && off < n)
643	    {
644	      off += (size_t)snprintf(buf + off, n - off, "%sCSC", off ? "+" : "");
645	    }
646	
647	  if ((mask & SENSOR_FEAT_CPS) != 0 && off < n)
648	    {
649	      off += (size_t)snprintf(buf + off, n - off, "%sCPS", off ? "+" : "");
650	    }
651	
652	  if ((mask & SENSOR_FEAT_BAT) != 0 && off < n)
653	    {
654	      (void)snprintf(buf + off, n - off, "%sBAT", off ? "+" : "");
655	    }
656	
657	  if (buf[0] == '\0')
658	    {
659	      (void)snprintf(buf, n, "-");
660	    }
