405	static int ble_companion_wait_gone(pid_t pid, unsigned wait_ms)
406	{
407	  unsigned steps;
408	  unsigned i;
409	
410	  if (pid <= 0)
411	    {
412	      return 0;
413	    }
414	
415	  steps = (wait_ms + 99u) / 100u;
416	  for (i = 0; i < steps; i++)
