418	      if (!ble_companion_pid_alive(pid))
419	        {
420	          return 0;
421	        }
422	
423	      usleep(100 * 1000);
424	    }
425	
426	  return ble_companion_pid_alive(pid) ? -ETIMEDOUT : 0;
427	}
