4000	  /* 本函数从 ble_companion 的 GATTS 回调（service-loop 线程）经
4001	   * companion_is_phone() 调用，而槽位地址由 companion 线程写。加锁保证
4002	   * memcmp 看到的是完整地址（写侧见 slot_bind_addr / slot_handle_disconnected）。 */
4003	  pthread_mutex_lock(&g_lock);
4004	  for (i = 0; i < SENSOR_KIND_COUNT; i++)
4005	    {
4006	      if (!addr_empty(&g_slots[i].addr) && addr_eq(&g_slots[i].addr, addr))
4007	        {
4008	          owned = true;
4009	          break;
4010	        }
4011	    }
4012	
4013	  pthread_mutex_unlock(&g_lock);
4014	
4015	  return owned;
4016	}
